package io.github.aimi.rag.workflow.core.model;

/**
 * Reserved metadata keys stored in a {@link FlowContext}.
 */
public final class FlowContextKeys {

    /** Execution id generated by {@code Flow.execute()} (a UUID by default). */
    public static final String EXECUTION_ID = "__execution_id";

    /** Name of the step currently being processed. */
    public static final String CURRENT_STEP = "__current_step";

    private FlowContextKeys() {
    }
}
